const controlHelp={
 'Color meaning':'Auto colors folder groups by system and other nodes by type. System follows original parent ancestry. Kind, depth and scope deliberately share colors when values match. The palette repeats; color alone is not a unique node ID.',
 'Shape meaning':'Kind uses square containers, rounded types/components and pill methods/events. Unity’s indented hierarchy defaults to rounded cards. Explicit node overrides take priority.',
 'Size meaning':'Uniform uses Base node size. Hierarchy reduces size with containment depth. Connections counts displayed relationship groups touching a node, not runtime activity or unique neighbors. Unity’s indented hierarchy keeps fixed readable dimensions.',
 'Node size gain':'Used only with Connections sizing outside the indented hierarchy. Auto rescales using the current projected graph; Fixed uses a stable count-to-size rule. Hover and clutter filters do not rescale nodes.',
 'Base node size':'Used only with Uniform sizing outside the indented Unity hierarchy.',
 'Arrow thickness gain':'Used only with Count thickness outside the indented hierarchy. Auto scales logarithmically relative to the current graph’s 90th percentile, multiplied by Line weight and capped at 6 graph units. Fixed uses a count multiplier. Zoom changes the on-screen thickness.',
 'Thickness meaning':'Uniform uses Line weight directly. Count makes aggregated relationships thicker. Counts describe static analysis records, not confidence, runtime traffic or importance.',
 'Arrow effect':'Auto animates calls, glows subscriptions and tapers inheritance. Per-type overrides take priority. Unknown/inferred evidence stays dashed. Reduced-motion disables flow animation. The indented hierarchy uses plain connectors.',
 'Line routing':'Curves, straight links or right-angle routes. Right-angle routing searches for corridors around nodes but cannot guarantee zero crossings. Indented hierarchy always uses parent rails.',
 'Line weight':'Base width in graph units, from 0.1 to 4. Count weighting can increase it. In the indented hierarchy, connector width is capped at 1. Zoom changes its screen size.',
 'Line visibility':'Opacity of connectors: 1 is opaque; lower values fade them. This does not change evidence confidence.',
 'Relationship labels':'Shows kind and aggregated count. Hover gives a tooltip; clicking opens evidence. Labels are suppressed in the indented hierarchy.',
 'Arrowheads':'Shows source-to-target direction outside the indented hierarchy. Heads have a fixed graph size, so zoom still scales them. They do not indicate execution order.',
 'Clutter control':'All retains the projected connections. Selected neighborhood retains links touching selected nodes. Strongest 30 keeps the largest record counts after Minimum records. Hover can temporarily narrow these further; no graph data is deleted.',
 'Minimum records':'Only show connectors with at least this many aggregated records. Containment links have count 1, so higher values hide them too.',
 'Apply node edits to':'All nodes creates a default for current and future nodes. Type applies to current/future nodes of that type. Visible and Selected target existing nodes only. Individual overrides take precedence; presets clear color/shape overrides.',
 'Bulk fill color':'Sets the targeted nodes’ accent color; the card fill is a muted tint of it. Does not change branch highlight colors.',
 'Bulk shape':'Sets the outline of the targeted nodes. Labels, notes and position locks are preserved.',
 'Typeface':'Selects a local system font family; unavailable fonts fall back to a generic family.',
 'Text size':'Sets label size outside the indented hierarchy, which uses 15-unit text. Long labels are shortened; hover for the full name.',
 'Border weight':'Sets node outlines outside the indented hierarchy, which uses a thin outline. Selection and branch highlights have their own outline styles.',
 'Depth':'Number of relationship steps to follow for Impact preview. Incoming finds users of the selection; outgoing finds its dependencies. Reachability does not prove a runtime effect.',
 'Display label':'Changes this node’s diagram name only. The source object or file is not renamed.',
 'Node color':'Overrides this node’s accent color. Applying a preset clears explicit color/shape overrides.',
 'Shape':'Overrides this node’s outline only.',
 'Notes':'Saved presentation notes for this node. Hover its card to read them.',
 'Rule':'Adds an architecture rule to the shared intent file. Required checks warn when missing; prohibited/direction/acyclic rules flag verified violations. This is not a visual preference and Ctrl+Z does not undo it; remove it in Issues.',
 'Theme':'Changes the canvas and panel theme for your presentation.',
 'Connections':'Default connector routing; the indented hierarchy uses its own rails.',
 'Snap to grid':'Rounds dragged node positions to 20-unit increments when released. Locked nodes do not move.',
 'Diagram description':'Presentation text saved with your layout; it does not alter code or architecture rules.',
 'Import layout':'Loads presentation JSON into your current preferences. It does not load another project’s graph.',
 'Starting branch':'Comparison uses each branch’s common ancestor with this reference. origin/main means your last locally fetched copy, not a live GitHub lookup.',
 'First branch':'One side of the merge-overlap check. Only locally available commits can be analyzed.',
 'Second branch':'The other side of the merge-overlap check. No branch switch or merge is performed.'
};
function addControlHelp(parent,title){let text=controlHelp[title];if(title.endsWith('line color'))text='Color for this relationship kind. It overrides its default palette color, not Git branch colors.';if(title.endsWith('arrow effect'))text='Effect for this relationship kind. Inherit uses the global Arrow effect. Indented hierarchy connectors remain plain.';if(text)help(parent,text);}
const sectionState=new Map();
function compartmentalize(p,openTitles=[]){let body=null;for(const child of [...p.children]){if(child.tagName==='H3'){const key=$('panelTitle').textContent+'|'+child.textContent,d=el('details',undefined,'panel-section');d.open=sectionState.has(key)?sectionState.get(key):openTitles.includes(child.textContent);const summary=el('summary',child.textContent);body=el('div',undefined,'section-body');d.append(summary,body);p.insertBefore(d,child);child.remove();d.ontoggle=()=>sectionState.set(key,d.open);}else if(body)body.append(child);}}

function visual(){return {colorBy:'auto',shapeBy:'kind',sizeBy:'connections',size:'standard',font:'system',fontSize:13,border:2,edgeWidth:2,edgeOpacity:.75,edgeLabels:false,arrows:true,nodeGain:'auto',arrowGain:'auto',edgeEffect:'auto',strength:'count',clutter:'all',minCount:1,...prefs.visual};}
function depthOf(n){let d=0,seen=new Set();while(n?.parent&&!seen.has(n.id)){seen.add(n.id);n=index().get(n.parent);d++;}return d;}
function colorFor(key){const semantic={editable:'#65d6bb',protected:'#ec9bc6',watch:'#f0b76e',undeclared:'#9aa9bf',calls:'#78bfff',references:'#65d6bb',inherits:'#b6a0ff',instantiates:'#f0b76e',contains:'#9aa9bf',depends:'#ec9bc6',group:'#78bfff',scene:'#65d6bb',prefab:'#b6a0ff',gameObject:'#f0b76e',component:'#ec9bc6',script:'#a8cc75',type:'#b6a0ff',method:'#65d6bb'};if(semantic[key])return semantic[key];if(typeof key==='number')return palette[key%palette.length];let hash=0;for(const c of String(key))hash=(hash*31+c.charCodeAt(0))>>>0;return palette[hash%palette.length];}
let visualCache=new Map(),gain={degrees:new Map(),nodeMax:1,edgeMax:1};
function updateGain(){const degrees=new Map(),counts=[];for(const l of relationshipCache.links.values()){degrees.set(l.a,(degrees.get(l.a)||0)+1);degrees.set(l.b,(degrees.get(l.b)||0)+1);counts.push(l.count);}const percentile=xs=>{xs.sort((a,b)=>a-b);return Math.max(1,xs[Math.floor((xs.length-1)*.9)]||1);};gain={degrees,nodeMax:percentile([...degrees.values()]),edgeMax:percentile(counts)};}
function gainScale(value,max){return Math.min(1,Math.log1p(value)/Math.log1p(Math.max(1,max)));}
function nodeVisual(n){if(visualCache.has(n.id))return visualCache.get(n.id);const v=visual(),d=depthOf(n),degree=gain.degrees.get(n.id)||0;const scale=v.sizeBy==='hierarchy'?Math.max(.72,1-d*.07):v.sizeBy==='connections'?(v.nodeGain==='auto'?.72+.28*gainScale(degree,gain.nodeMax):Math.min(1,.72+degree*.035)):({compact:.72,standard:.88,large:1}[v.size]||.88);const key=v.colorBy==='auto'?(n.kind==='group'?systemOf(n):n.kind):v.colorBy==='hierarchy'?d:v.colorBy==='system'?systemOf(n):v.colorBy==='scope'?scope(n)||'undeclared':n.kind;const result={width:hierarchyMode()?280:overviewMode()?240:220*scale,height:hierarchyMode()?76:overviewMode()?96:76*scale,shape:(hierarchyMode()||overviewMode())?'rounded':v.shapeBy==='kind'?(['group','scene','prefab','context'].includes(n.kind)?'square':['method','event'].includes(n.kind)?'pill':'rounded'):v.shapeBy,color:v.colorBy==='uniform'?'#273849':colorFor(key),...prefs.allStyle,...prefs.typeStyles?.[n.kind],...prefs.nodes[n.id]};visualCache.set(n.id,result);return result;}
function navigateTo(id){cancelPreview();focus=id;selected.clear();$('search').value='';camera={x:0,y:0,z:1};render();fit();}
function navigation(){const c=$('crumb');c.replaceChildren();const trail=[],seen=new Set();let n=displayNodes().find(n=>n.id===focus);while(n&&!seen.has(n.id)){seen.add(n.id);trail.unshift(n);n=displayNodes().find(x=>x.id===n.parent);}button(c,'⌂ Project',()=>navigateTo(null));for(const n of trail){c.append(el('span',' › '));button(c,n.label,()=>navigateTo(n.id));}$('back').disabled=!focus;$('back').textContent='← Back';$('back').title='Back to parent (Alt + Left arrow)';}
function visualChange(change){cancelPreview();checkpoint();change();render();save();}
