 if(elkMode())p.append(el('p','ELK manages node positions and orthogonal routes. Line routing and manual dragging apply in other layouts. Size changes automatically recalculate this layout.','mode-note'));if(hierarchyMode())p.append(el('p','Unity hierarchy uses fixed readable card sizes, thin outlines and plain parent rails. Size, text-size and arrow-effect preferences apply in other layouts.','mode-note'));p.append(el('h3','Start with a visual language'));for(const [name,config]of Object.entries({'Adaptive overview':{colorBy:'auto',shapeBy:'kind',sizeBy:'connections'},'Node types':{colorBy:'kind',shapeBy:'kind',sizeBy:'uniform'},'Hierarchy':{colorBy:'hierarchy',shapeBy:'kind',sizeBy:'hierarchy'},'System families':{colorBy:'system',shapeBy:'rounded',sizeBy:'uniform'},'Connection hubs':{colorBy:'kind',shapeBy:'kind',sizeBy:'connections'},'Change scopes':{colorBy:'scope',shapeBy:'kind',sizeBy:'uniform'},'Quiet monochrome':{colorBy:'uniform',shapeBy:'rounded',sizeBy:'uniform'}}))button(p,name,()=>{visualChange(()=>{prefs.visual={...visual(),...config};prefs.typeStyles={};prefs.allStyle={};for(const st of Object.values(prefs.nodes)){delete st.color;delete st.shape;}});stylesPanel();});
