 select(p,'Color meaning',['auto','kind','system','hierarchy','scope','uniform'],v.colorBy,x=>set('colorBy',x));select(p,'Shape meaning',['kind','rounded','square','pill'],v.shapeBy,x=>set('shapeBy',x));select(p,'Size meaning',['uniform','hierarchy','connections'],v.sizeBy,x=>set('sizeBy',x));select(p,'Node size gain',['auto','fixed'],v.nodeGain,x=>set('nodeGain',x));select(p,'Base node size',['compact','standard','large'],v.size,x=>set('size',x));select(p,'Typeface',['system','rounded','monospace'],v.font,x=>set('font',x));select(p,'Text size',['11','13','15','17'],String(v.fontSize),x=>set('fontSize',+x));select(p,'Border weight',['1','2','3','4'],String(v.border),x=>set('border',+x));
 p.append(el('h3','Connections'));select(p,'Arrow effect',['auto','plain','dashed','flowing','glowing','tapered'],v.edgeEffect,x=>set('edgeEffect',x));select(p,'Arrow thickness gain',['auto','fixed'],v.arrowGain,x=>set('arrowGain',x));select(p,'Thickness meaning',['uniform','count'],v.strength,x=>set('strength',x));select(p,'Clutter control',['all','selected neighborhood','strongest 30'],v.clutter,x=>set('clutter',x));select(p,'Minimum records',['1','2','5','10','25'],String(v.minCount),x=>set('minCount',+x));select(p,'Line routing',['curve','straight','orthogonal'],prefs.route,x=>visualChange(()=>{prefs.route=x;}));select(p,'Line weight',['0.1','0.25','0.5','0.75','1','2','3','4'],String(v.edgeWidth),x=>set('edgeWidth',+x));select(p,'Line visibility',['0.3','0.5','0.75','1'],String(v.edgeOpacity),x=>set('edgeOpacity',+x));select(p,'Relationship labels',['off','on'],v.edgeLabels?'on':'off',x=>set('edgeLabels',x==='on'));select(p,'Arrowheads',['on','off'],v.arrows?'on':'off',x=>set('arrows',x==='on'));
 p.append(el('h3','By relationship type'));for(const kind of [...new Set(state.graph.edges.map(e=>e.kind))].sort()){const typePanel=el('details',undefined,'relationship-section');typePanel.append(el('summary',kind));p.append(typePanel);select(typePanel,kind+' arrow effect',['inherit','plain','dashed','flowing','glowing','tapered'],prefs.edgeEffects?.[kind]||'inherit',x=>visualChange(()=>{prefs.edgeEffects??={};if(x==='inherit')delete prefs.edgeEffects[kind];else prefs.edgeEffects[kind]=x;}));field(typePanel,kind+' line color','color',prefs.edgeColors?.[kind]||colorFor(kind),x=>visualChange(()=>{prefs.edgeColors={...prefs.edgeColors,[kind]:x};}));}
 p.append(el('h3','Bulk node overrides'));p.append(el('p','Overrides take priority over presets. Choose a target, then change color or shape. Labels, notes and position locks are preserved.'));
