 const bulk=(key,value)=>{const nodes=target==='Visible nodes'?visible:target==='Selected nodes'?displayNodes().filter(n=>selected.has(n.id)):target.startsWith('Type: ')?displayNodes().filter(n=>n.kind===target.slice(6)):displayNodes();if(!nodes.length)return banner('Select nodes on the canvas first (Shift-click to select several).');visualChange(()=>{if(target.startsWith('Type: ')){prefs.typeStyles??={};prefs.typeStyles[target.slice(6)]={...prefs.typeStyles[target.slice(6)],[key]:value};}if(target==='All nodes'){prefs.allStyle={...prefs.allStyle,[key]:value};for(const st of Object.values(prefs.nodes))delete st[key];for(const st of Object.values(prefs.typeStyles||{}))delete st[key];}else if(!target.startsWith('Type: '))for(const n of nodes){if(n.kind==='context')continue;prefs.nodes[n.id]={...prefs.nodes[n.id],[key]:value};}else for(const n of nodes)if(prefs.nodes[n.id])delete prefs.nodes[n.id][key];});};
