function styleTabs(p){
 const groups={'Presets':['Start with a visual language'],'Nodes':['Node appearance','Bulk node overrides'],'Arrows':['Connections','By relationship type'],'Sharing':['Reset & share']};
 const tabs=el('div',undefined,'style-tabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Style categories');
 for(const name of Object.keys(groups)){const b=el('button',name);b.setAttribute('role','tab');b.setAttribute('aria-selected',String(styleTab===name));b.onclick=()=>{styleTab=name;stylesPanel();};tabs.append(b);}p.prepend(tabs);
 for(const section of p.querySelectorAll(':scope > .panel-section')){const title=section.querySelector('summary').textContent;section.hidden=!groups[styleTab].includes(title);section.open=groups[styleTab][0]===title;if(title==='Start with a visual language'){section.classList.add('preset-gallery');for(const b of section.querySelectorAll('.section-body > button')){const swatches=el('span',undefined,'preset-swatches');for(const color of (b.textContent==='Quiet monochrome'?['#9aa9bf','#607089','#36445b']:palette.slice(0,4))){const swatch=el('i');swatch.style.background=color;swatches.append(swatch);}b.setAttribute('aria-label',b.textContent);b.prepend(swatches);const hint=el('small',({'Adaptive overview':'Systems + connection sizes','Node types':'Color and shape by type','Hierarchy':'Color and size by depth','System families':'Color by system or folder','Connection hubs':'Larger = more connections','Change scopes':'Editable, protected and watch','Quiet monochrome':'One quiet color'})[b.textContent]);b.append(hint);}}}
}
function styleLegend(){const v=visual(),box=$('legend');box.replaceChildren();box.append(el('strong','Color: '+v.colorBy+' · Size: '+v.sizeBy));const keys=new Map();for(const n of visible){const key=v.colorBy==='auto'?(n.kind==='group'?systemOf(n):n.kind):v.colorBy==='hierarchy'?'Level '+depthOf(n):v.colorBy==='system'?systemOf(n):v.colorBy==='scope'?scope(n)||'undeclared':v.colorBy==='uniform'?'All nodes':n.kind;if(!keys.has(key))keys.set(key,nodeVisual(n).color);}for(const [key,color]of [...keys].slice(0,12)){const item=el('span',key),swatch=el('i');swatch.style.background=color;item.prepend(swatch);box.append(item);}for(const kind of [...new Set([...relationshipCache.links.values()].map(l=>l.e.kind))]){const item=el('span','→ '+kind),swatch=el('i');swatch.style.background=prefs.edgeColors?.[kind]||colorFor(kind);item.prepend(swatch);box.append(item);}box.append(el('small',(v.nodeGain==='auto'||v.arrowGain==='auto'?'Auto gain uses this view’s relationships. Unity hierarchy keeps fixed node sizes. ':'')+'Shapes by kind: square containers · rounded types/components · pill methods/events. Individual overrides may differ. Larger hierarchy nodes = containers; larger hubs = more visible connections. Dashed lines may indicate inferred evidence or a chosen effect. Click a connector to check its evidence.'));}

function drill(n){if(n.kind==='context')return;if(displayNodes().some(x=>x.parent===n.id)){navigateTo(n.id);}else showSource(n);}
function dragNode(event,n){if(n.kind==='context')return;if(overviewMode()){event.stopPropagation();if(!event.shiftKey)selected.clear();if(event.shiftKey&&selected.has(n.id))selected.delete(n.id);else selected.add(n.id);inspect(n);render();return;}if(event.button!==0)return;event.stopPropagation();if(!event.shiftKey&&!selected.has(n.id))selected.clear();if(event.shiftKey&&selected.has(n.id))selected.delete(n.id);else selected.add(n.id);inspect(n);render();if(elkMode())return;checkpoint();const start={x:event.clientX,y:event.clientY},initial=Object.fromEntries([...selected].map(id=>[id,{...positions[id]}]));let moved=false;const move=e=>{const dx=(e.clientX-start.x)/camera.z,dy=(e.clientY-start.y)/camera.z;if(Math.abs(dx)+Math.abs(dy)>3)moved=true;for(const [id,p]of Object.entries(initial)){if(prefs.nodes[id]?.locked)continue;positions[id]={x:p.x+dx,y:p.y+dy};}render();};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(moved&&prefs.snap)for(const id of selected){if(prefs.nodes[id]?.locked)continue;positions[id].x=Math.round(positions[id].x/20)*20;positions[id].y=Math.round(positions[id].y/20)*20;}if(moved)render();save();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);document.querySelectorAll('.node').forEach(g=>g.classList.toggle('selected',selected.has(g.dataset.id)));}
function panel(title){$('inspector').hidden=false;$('inspector').classList.toggle('git-panel',title.startsWith('Git'));$('inspector').scrollTop=0;$('panelTitle').textContent=title;$('panel').replaceChildren();return $('panel');}
function button(parent,label,action){let b=el('button',label);b.onclick=()=>Promise.resolve(action()).catch(e=>banner(e.message));parent.append(b);return b;}
function field(parent,title,type,value,change){let label=el('label',title),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.setAttribute('aria-label',title);input.value=value??'';input.onchange=()=>change(input.value);label.append(input);parent.append(label);if(type!=='file')addControlHelp(parent,title);return input;}
function select(parent,title,values,current,change){let label=el('label',title),s=el('select');s.setAttribute('aria-label',title);for(const value of values){const optionLabels={auto:'Automatic',kind:'Node type',system:'System / folder',hierarchy:'Hierarchy depth',scope:'Change scope',uniform:'Uniform',connections:'Connection count',count:'Relationship count',fixed:'Fixed scale',inherit:'Use global setting'};let o=el('option',optionLabels[value]||value);o.value=value;s.append(o);}s.value=current;s.onchange=()=>Promise.resolve(change(s.value)).catch(e=>banner(e.message));label.append(s);parent.append(label);addControlHelp(parent,title);return s;}
function editStyle(n,key,value){checkpoint();prefs.nodes[n.id]={...prefs.nodes[n.id],[key]:value};render();save();}
function inspect(n){if(n.kind==='context'){const p=panel(n.label);p.append(el('p','Navigation context. These hierarchy links organize the displayed nodes; they are not method calls.'));return;}const p=panel(n.label);p.append(el('p',n.path?`${n.path}${n.line?':'+n.line:''}`:n.kind),el('p',`Evidence: ${n.status}. Scope: ${scope(n)||'not declared'}.`));button(p,'Explore',()=>drill(n));if(n.path){button(p,'Source',()=>showSource(n));button(p,'Local diff',()=>showDiff(n));}p.append(el('h3','Change scope'));help(p,'Applies to selected nodes and is inherited by descendants. Editable is a declaration; Protected reports changed files as errors; Watch reports them for review. These do not block Unity edits. Inherit removes the explicit declaration. Scope edits write shared intent and are not undone by visual Undo.');for(const s of ['editable','protected','watch'])button(p,s[0].toUpperCase()+s.slice(1),()=>setScope(s));button(p,'Inherit',()=>setScope(null));p.append(el('h3','Impact preview'));let depth=2;select(p,'Depth',['1','2','3','5'],String(depth),v=>depth=+v);for(const incoming of [true,false])button(p,incoming?'Incoming dependencies':'Outgoing dependencies',()=>{impact=new Set();let front=new Set(selected);for(let i=0;i<depth;i++){let next=new Set();for(const e of state.graph.edges){if(e.kind==='contains')continue;let from=incoming?e.target:e.source,to=incoming?e.source:e.target;if(front.has(from)&&!impact.has(to)){impact.add(to);next.add(to);}}front=next;}render();p.append(el('p',`${impact.size} related nodes. Structural reachability indicates possible impact, not guaranteed behavior.`));});p.append(el('h3','Presentation'));button(p,'Create visual module from selection',()=>{const label=window.prompt('Module name');if(!label?.trim())return;checkpoint();const members=[...selected].filter(id=>state.graph.nodes.some(x=>x.id===id));if(!members.length)return banner('Select real project nodes to create a module.');prefs.modules??={};const id='visual:'+crypto.randomUUID();prefs.modules[id]={label:label.trim(),members};view='custom';positions=prefs.views[view]||{};focus=id;$('search').value='';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();save();});if(prefs.modules?.[n.id])button(p,'Dissolve visual module',()=>{checkpoint();delete prefs.modules[n.id];focus=null;render();save();});field(p,'Display label','text',prefs.nodes[n.id]?.label||n.label,v=>editStyle(n,'label',v));field(p,'Node color','color',prefs.nodes[n.id]?.color||'#243344',v=>editStyle(n,'color',v));select(p,'Shape',['rounded','square','pill'],prefs.nodes[n.id]?.shape||'rounded',v=>editStyle(n,'shape',v));field(p,'Notes','textarea',prefs.nodes[n.id]?.note||'',v=>editStyle(n,'note',v));button(p,prefs.nodes[n.id]?.locked?'Unlock position':'Lock position',()=>{editStyle(n,'locked',!prefs.nodes[n.id]?.locked);inspect(n);});p.append(el('h3','Relationships'));const related=state.graph.edges.filter(e=>e.source===n.id||e.target===n.id);for(const e of related.slice(0,40))button(p,`${e.kind}: ${state.graph.nodes.find(x=>x.id===(e.source===n.id?e.target:e.source))?.label||'Unknown'}`,()=>inspectEdge(e));if(related.length>40)p.append(el('p',`${related.length-40} additional relationships; use search to narrow the graph.`));compartmentalize(p,['Change scope']);}
async function setScope(value){if(offline)throw Error('Scope rules can be changed in the local dashboard.');const intent=structuredClone(state.intent);for(const selectedId of selected)for(const id of (prefs.modules?.[selectedId]?.members||[selectedId])){if(value)intent.scopes[id]=value;else delete intent.scopes[id];}await api('/api/intent',intent);state.intent=intent;state=await api('/api/state');render();if(selected.size){const n=displayNodes().find(n=>n.id===[...selected][0]);if(n)inspect(n);}}
function inspectEdge(e,count=1){const p=panel('Relationship evidence');for(const [label,value]of Object.entries({source:state.graph.nodes.find(n=>n.id===e.source)?.label||e.source,target:state.graph.nodes.find(n=>n.id===e.target)?.label||e.target,relationship:e.kind,status:e.status,analysis:e.method,evidence:e.evidence,location:e.path+':'+e.line}))p.append(el('h3',label),el('p',value));if(count>1)p.append(el('p',`${count} relationships are aggregated in this arrow. This inspector shows one source record.`));button(p,'Inspect source',()=>showSource({path:e.path,line:e.line,label:'Relationship'}));if(!offline){select(p,'Rule',['prohibited','required','direction','acyclic'],'prohibited',v=>p.dataset.rule=v);button(p,'Add architecture rule',async()=>{const intent=structuredClone(state.intent);intent.rules.push({id:crypto.randomUUID(),source:e.source,target:e.target,kind:e.kind,mode:p.dataset.rule||'prohibited'});await api('/api/intent',intent);state=await api('/api/state');render();showIssues();});}}
async function showSource(n){if(offline){banner('Local source is not included in shared snapshots. Open the local dashboard for source inspection.');return;}try{const text=await api('/api/source?path='+encodeURIComponent(n.path));$('sourceTitle').textContent=`${n.path}:${n.line||1}`;$('sourceText').textContent=text.split('\n').map((line,i)=>`${String(i+1).padStart(5)}  ${line}`).join('\n');$('source').showModal();$('sourceText').scrollIntoView();}catch(e){banner('Source preview unavailable: '+e.message);}}
async function showDiff(n){if(offline)return banner('Diffs are available in the local dashboard.');$('sourceTitle').textContent='Local Git diff · '+n.path;$('sourceText').textContent=await api('/api/diff?path='+encodeURIComponent(n.path))||'No tracked diff. Untracked content has no Git baseline.';$('source').showModal();}
function showIssues(){const p=panel('Architecture & scope');p.append(el('p','Errors enforce explicit rules. Unknown relationships and missing requirements need review.'));for(const i of state.issues||[]){let row=el('div',undefined,'row');row.append(el('strong',i.severity+' · '+i.code),el('p',i.message));if(i.evidence)button(row,'Evidence',()=>inspectEdge(i.evidence));if(i.source)button(row,'Select node',()=>{const n=state.graph.nodes.find(n=>n.id===i.source);if(n){$('search').value=n.label;selected=new Set([n.id]);render();inspect(n);}});p.append(row);}p.append(el('h3','Configured rules'));for(const rule of state.intent.rules){let row=el('div',undefined,'row');row.append(el('p',rule.mode+' '+rule.kind+' · '+rule.id));if(!offline)button(row,'Remove rule',async()=>{const intent=structuredClone(state.intent);intent.rules=intent.rules.filter(r=>r.id!==rule.id);await api('/api/intent',intent);state=await api('/api/state');showIssues();render();});p.append(row);}p.append(el('h3','Analysis coverage'));for(const i of state.graph.issues.slice(0,80))p.append(el('p',i.message));if(state.graph.issues.length>80)p.append(el('p',`${state.graph.issues.length-80} additional diagnostics in the exported graph.`));}

